package android.view;public class ViewGroup extends View {public final java.util.List<View> children=new java.util.ArrayList<>();public ViewGroup(android.content.Context c){super(c);}public void addView(View v,Object p){v.parent=this;v.layoutParams=p;children.add(v);}public View findViewById(int id){View v=super.findViewById(id);if(v!=null)return v;for(View child:children){v=child.findViewById(id);if(v!=null)return v;}return null;}public View findViewWithTag(Object t){View v=super.findViewWithTag(t);if(v!=null)return v;for(View child:children){v=child.findViewWithTag(t);if(v!=null)return v;}return null;}}